import{_ as o,l as n,o as e,c as s,v as r,p as l,x as t,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"卡诺图与化简","description":"","frontmatter":{"title":"卡诺图与化简","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/karnaugh-map.md","filePath":"cs/karnaugh-map.md","lastUpdated":1789023840000}'),c={name:"cs/karnaugh-map.md"};function E(u,a,m,_,B,A){const i=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="卡诺图与化简" tabindex="-1">卡诺图与化简 <a class="header-anchor" href="#卡诺图与化简" aria-label="Permalink to &quot;卡诺图与化简&quot;">​</a></h1><div class="epigraph"><p>相邻的最小项只差一个变量，圈在一起就能消掉那个变量；图把相邻画成格子的邻居。</p><footer>—— 据 Karnaugh, The Map Method for Synthesis of Combinational Logic Circuits, 1953；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/minterm-maxterm">最小项与最大项</a>钉死了规范 SOP/POS。本课不重列 \\(2^n\\) 个最小项，也不从「逻辑综合史」另起。缺口是：规范式通常太长。电路要的是更少的门、更短的式，同时<strong>保持 1-集合不变</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 稍大，规范或项数就是真值表里 1 的个数，没法直接铺门。代数反复用吸收律可以化简，但没有视觉上的「哪些项能合并」。缺口因此不是新的函数类，而是一种排列：把最小项放进格雷码网格，使得几何相邻 \\(\\Leftrightarrow\\) 汉明距离 1，于是 \\(2^k\\) 个相邻 1 合成一个消去 \\(k\\) 个变量的乘积项。</p><p>卡诺图对 \\(n\\le 4\\) 好用，\\(n=5,6\\) 要对折。更大规模交给列表法，本课不展开 Quine–McCluskey。无关项与险象故意留到<a href="/cs/dont-care-hazard">下一课</a>。</p><h3 id="圈不是「把所有-1-圈进一个最大圈」" tabindex="-1">圈不是「把所有 1 圈进一个最大圈」 <a class="header-anchor" href="#圈不是「把所有-1-圈进一个最大圈」" aria-label="Permalink to &quot;圈不是「把所有 1 圈进一个最大圈」&quot;">​</a></h3><p>每个 1 必须被至少一个质蕴涵项覆盖；圈要乘 2 的幂、不能斜切。贪心画一个最大圈可能迫使别处补很多小圈。本课只要求：合法圈对应乘积项，覆盖完整。最优覆盖是集合覆盖，图上靠眼力，不是多项式算法。</p><p><span class="marginnote">Karnaugh 1953 把 Veitch 图改成格雷码相邻。Harris 用它当手算综合的主工具。本栏后课的 ALU 控制逻辑，默认已经会从真值表收成几项。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 \\(2^n\\) 格，行、列按格雷码标变量。填 1/0。圈 \\(1,2,4,8,\\ldots\\) 个相邻 1（含卷绕相邻）。每个圈读出不变的变量得乘积项，所有圈的或即化简 SOP。对偶可圈 0 得 POS。</p>',11)),(e(),l(p,null,{default:t(()=>[h(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SOP%5B%22%E8%A7%84%E8%8C%83%E6%9C%80%E5%B0%8F%E9%A1%B9%E4%B9%8B%E5%92%8C%22%5D%20--%3E%20MAP%5B%22%E6%A0%BC%E9%9B%B7%E7%A0%81%E7%BD%91%E6%A0%BC%22%5D%0A%20%20MAP%20--%3E%20GROUP%5B%222%5Ek%20%E7%9B%B8%E9%82%BB%E5%9C%88%22%5D%0A%20%20GROUP%20--%3E%20MIN%5B%22%E8%BE%83%E5%B0%91%E4%B9%98%E7%A7%AF%E9%A1%B9%22%5D%0A%20%20MIN%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%97%A0%E5%85%B3%E9%A1%B9%E4%B8%8E%E9%99%A9%E8%B1%A1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>合并的本质是上一课纠错直觉里的距离：差一位的两个最小项，那个变量成为无关，式子变短。功能集合不变，延迟和面积通常下降——「通常」是因为多级因式分解还能再短，卡诺图只管两级 SOP。后课门时延会说明：两级与或的深度固定，项再少，关键路径仍可能被扇出拖住。</p><p>同一函数的 SOP 与 POS 哪个更短，看 1 多还是 0 多。本课两种都合法。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课默认函数完全指定、输入同时到达。竞争与静态险象、以及 \\(X\\) 无关项，下一课才加。也不把 HDL 综合器的算法写成步骤。</p><p>后课默认：手算组合逻辑从真值表进卡诺图得到两级式；不完全指定与毛刺另处理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>卡诺图把汉明距离 1 画成格子相邻，合并即消去变量。</li><li>圈须为 2 的幂并覆盖全部 1；最短覆盖仍可能要试。</li><li>只管两级 SOP/POS；多级分解与时序不在本课。</li><li>出处：Karnaugh, 1953；Harris and Harris。</li></ul>',8))])}const S=o(c,[["render",E]]);export{f as __pageData,S as default};
